async (page) => {
  const b = page.context().browser();
  const out = {};
  // 1) PC 首页模型入口
  const c1 = await b.newContext({viewport:{width:1920,height:1080},locale:'en-US'});
  const pc = await c1.newPage();
  await pc.goto('http://10.17.1.66:3001/en', {waitUntil:'domcontentloaded'});
  await pc.waitForTimeout(6000);
  out.pcModelButtonTexts = await pc.evaluate(() => Array.from(document.querySelectorAll('button')).map(x => (x.innerText||'').trim()).filter(t => t && t.length < 30).slice(0, 40));
  const modelBtn = pc.locator('button', {hasText:'Auto'}).first();
  out.pcModelBtnFound = await modelBtn.count();
  if (out.pcModelBtnFound) {
    await modelBtn.click();
    await pc.waitForTimeout(1200);
    out.pcPopupVisible = await pc.locator('.cinematic-popup').first().isVisible().catch(() => false);
    out.pcPopupText = (await pc.locator('.cinematic-popup').first().innerText().catch(() => '')).slice(0, 400);
  }
  await pc.screenshot({path:'artifacts/2026-09-14_stable_regression_all_archived/evidence/mcp_drift_20260914/pc_home_model_menu.png'});
  // 2) /create 促销弹窗（全新上下文）
  const c2 = await b.newContext({viewport:{width:1920,height:1080},locale:'en-US'});
  const cp = await c2.newPage();
  await cp.goto('http://10.17.1.66:3001/en/create', {waitUntil:'domcontentloaded'});
  await cp.waitForTimeout(8000);
  out.promoTexts = await cp.evaluate(() => Array.from(document.querySelectorAll('div[class*=fixed],div[class*=modal],div[class*=dialog]')).map(d => (d.innerText||'').trim()).filter(t => /1 USD|VIP|limited-time/i.test(t)).slice(0, 3).map(t => t.slice(0, 300)));
  out.closeBtnCount = await cp.getByRole('button', {name:/close/i}).count();
  out.closeCandidates = await cp.evaluate(() => Array.from(document.querySelectorAll('button,img,svg,div')).filter(e => { const r = e.getBoundingClientRect(); return r.width > 20 && r.width < 60 && r.height > 20 && r.height < 60; }).slice(0, 12).map(e => e.tagName + '|' + (e.className||'').slice(0, 60)));
  await cp.screenshot({path:'artifacts/2026-09-14_stable_regression_all_archived/evidence/mcp_drift_20260914/create_promo_popup.png'});
  return JSON.stringify(out);
}
